// RUN: %{build} -o %t.out
// RUN: %{run} %t.out

// An inline user-provided name must work for both the main and auxiliary
// kernels generated by a multi-reduction.
#include <sycl/detail/core.hpp>
#include <sycl/reduction.hpp>

#include <cassert>

template <class Name, class RangeT> void test(sycl::queue &Q, RangeT Range) {
  int A = 0, B = 0;
  {
    sycl::buffer<int> OutA(&A, sycl::range<1>{1});
    sycl::buffer<int> OutB(&B, sycl::range<1>{1});
    Q.submit([&](sycl::handler &CGH) {
       auto SumA = sycl::reduction(OutA, CGH, sycl::plus<int>{});
       auto SumB = sycl::reduction(OutB, CGH, sycl::plus<int>{});
       CGH.parallel_for<Name>(Range, SumA, SumB, [](auto, auto &X, auto &Y) {
         X += 1;
         Y += 2;
       });
     }).wait_and_throw();
  }
  assert(A == 16 && B == 32);
}

int main() {
  sycl::queue Q;
  test<class InlineRangeReduction>(Q, sycl::range<1>{16});
  test<class InlineNDRangeReduction>(
      Q, sycl::nd_range<1>{sycl::range<1>{16}, sycl::range<1>{8}});
}
